package vn.codegym.inotes;import java.util.*;public class NoteManagement{private NoteStrategy strategy;public NoteManagement(NoteStrategy strategy){this.strategy=strategy;}public void setStrategy(NoteStrategy strategy){this.strategy=strategy;}public void addNote(String title,String content,int typeId)throws Exception{strategy.save(new Note(0,title,content,typeId));}public void deleteNote(int id)throws Exception{strategy.delete(id);}public List<Note> searchNotes(String keyword)throws Exception{return strategy.search(keyword);}public List<Note> findAll()throws Exception{return strategy.findAll();}}
